site_tls:
# guest site blog-anna.example.test -> sandbox 172.31.250.11:3000 (managed by sitegate)
server {
    listen 80;
    listen [::]:80;
    server_name blog-anna.example.test;
    location ^~ /.well-known/acme-challenge/ { root /var/www/html; }
    location / { return 301 https://$host$request_uri; }
}

server {
    listen 443 ssl;
    listen [::]:443 ssl;
    server_name blog-anna.example.test;
    ssl_certificate /etc/letsencrypt/live/blog-anna.example.test/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/blog-anna.example.test/privkey.pem;
    include /etc/letsencrypt/options-ssl-nginx.conf;
    ssl_dhparam /etc/letsencrypt/ssl-dhparams.pem;
    client_max_body_size 50m;
    location / {
        proxy_pass http://172.31.250.11:3000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection $http_connection;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        proxy_read_timeout 300s;
    }
}

